function drawEnvironment(){const b=activeFight;if(!b.environment)return;for(const z of b.zones||[]){ctx.save();ctx.globalAlpha=.24;const spriteIndex={fire:0,lava:0,shadow:11,gravity:4,life:12,bramble:8,seedburst:8}[z.type];sprite('effects',spriteIndex,z.x,z.y,z.radius*2,0,.25);ctx.strokeStyle=['life','bramble','seedburst'].includes(z.type)?'#96d7a5':z.type==='gravity'?'#ad88d6':'#b57862';ctx.lineWidth=1;ctx.beginPath();ctx.arc(z.x,z.y,z.radius,0,Math.PI*2);ctx.stroke();ctx.restore();}for(const o of b.obstacles||[])sprite('effects',8,o.x,o.y,o.radius*2+5);for(const f of b.fighters){if(f.illusionTime>0&&f.decoy?.hp>0){ctx.fillStyle=teamOf(f)?'#ff5a6a80':'#3ee0ff80';ctx.beginPath();ctx.arc(f.decoy.x,f.decoy.y,9,0,Math.PI*2);ctx.fill();}if(f.portalTime>0&&f.gates)for(const gate of f.gates)sprite('effects',15,gate.x,gate.y,30);if(f.soul>0){const owner=b.fighters[f.soulOwner];ctx.strokeStyle='#9871c5';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(owner.x,owner.y);ctx.lineTo(f.x,f.y);ctx.stroke();}if(f.flight>0||f.foreseen>0||f.wardHits>0)sprite('effects',f.flight>0?7:f.foreseen>0?10:14,f.x,f.y,30,0,.45);}for(const s of b.summons||[])sprite('effects',s.type==='spirit'?4:7,s.x,s.y,s.type==='spirit'?13:16);for(const w of b.wisps||[]){if(w.hp<=0)continue;ctx.fillStyle='#d4e4c5';ctx.beginPath();ctx.arc(w.x,w.y,4,0,Math.PI*2);ctx.fill();}for(const food of b.food||[]){if(food.ready>b.time)continue;ctx.strokeStyle='#9cc578';ctx.strokeRect(food.x-4,food.y-4,8,8);}if(b.relic?.active){sprite('effects',4,b.relic.x,b.relic.y,28,0,.5);ctx.strokeStyle='#ad86d548';ctx.lineWidth=1;ctx.beginPath();ctx.arc(b.relic.x,b.relic.y,b.relic.radius,0,Math.PI*2);ctx.stroke();}if(['rain','storm'].includes(b.environment.weather)){ctx.strokeStyle='#b9d5e52a';ctx.lineWidth=1;for(let i=0;i<40;i++){const x=(i*137+b.time*25)%600,y=(i*73+b.time*95)%600;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+9);ctx.stroke();}}if(b.environment.weather==='frost'){ctx.strokeStyle='#b0d5e925';ctx.strokeRect(13,13,574,574);}}

